 {"id": "PEDS-C29-054", "sec": "Diagnosis", "page": 131, "q": "The newborn screening test for CF is the immunoreactive ___ test.", "opts": ["amylase", "elastase", "trypsin", "lipase"], "ans": 2, "exp": "Immunoreactive trypsin test (IRT) (Book p131)", "type": "fill"},
 {"id": "PEDS-C29-055", "sec": "Lab evidence", "page": 132, "q": "Cystic fibrosis is confirmed by any ___ positive laboratory test.", "opts": ["two", "three", "four", "one"], "ans": 3, "exp": "Laboratory evidence: any 1 positive lab test confirms CF (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-056", "sec": "Lab evidence", "page": 132, "q": "A diagnostic sweat chloride concentration is greater than ___ mEq/L on separate days.", "opts": ["60", "40", "80", "100"], "ans": 0, "exp": "Sweat chloride concentration >60 mEq/L on separate days (Book p132)", "type": "fill"},
 {"id": "PEDS-C29-057", "sec": "Lab evidence", "page": 132, "q": "The genetic criterion for CF diagnosis requires identification of ___ CF mutations.", "opts": ["4", "2", "1", "3"], "ans": 1, "exp": "Identification of 2 CF mutations (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-058", "sec": "Lab evidence", "page": 132, "q": "The third laboratory evidence for CF is an abnormal value of —", "opts": ["Urine osmolality after water deprivation", "Nasal mucus pH with potassium assay", "Trans-epithelial nasal potential difference", "Serum chloride with venous blood gas"], "ans": 2, "exp": "1 abnormal value of trans epitelial nasal potential difference (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-059", "sec": "Diagnosis", "page": 132, "q": "Match the CF diagnostic elements — select the correct combination:", "pairs": [["Newborn screening", "Any 1 positive test"], ["Sibling history", "Autosomal recessive"], ["Lab confirmation rule", ">60 mEq/L"], ["Sweat chloride cutoff", "Immunoreactive trypsin (IRT)"]], "opts": ["A-4, B-2, C-3, D-1", "A-2, B-4, C-1, D-3", "A-4, B-1, C-2, D-3", "A-4, B-2, C-1, D-3"], "ans": 3, "exp": "Correct: newborn screen→IRT; sibling→AR; lab rule→any 1 positive; sweat Cl→>60 mEq/L. (Book p131–132)", "type": "match"},
 {"id": "PEDS-C29-060", "sec": "Sweat test", "page": 132, "q": "The sweat chloride test is performed using —", "opts": ["Pilocarpine iontophoresis", "PEG tube collection", "Tape stripping of the skin", "Nasal brushing"], "ans": 0, "exp": "Pilocarpine iontophoresis (sweat chloride test) (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-061", "sec": "Sweat test", "page": 132, "q": "In pilocarpine iontophoresis, pilocarpine is administered —", "opts": ["Orally in drops after each feed", "Into the skin of the baby using electrodes", "Intravenously through a peripheral cannula", "By nebulization through a face mask"], "ans": 1, "exp": "Pilocarpine administered into skin of baby using electrodes (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-062", "sec": "Sweat test", "page": 132, "q": "The baby's sweat is collected in a collection device and processed for —", "opts": ["pH", "Osmolality", "Cl⁻ levels", "Na⁺ levels"], "ans": 2, "exp": "Sweat collected in collection device which processes it for Cl⁻ levels (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-063", "sec": "Sweat test", "page": 132, "stem": "A newborn screen is positive for cystic fibrosis. The infant is otherwise asymptomatic.", "q": "The confirmatory test of choice is —", "opts": ["Immediate CFTR modulator therapy", "Repeat IRT after one month", "High-resolution CT chest", "Sweat chloride test (pilocarpine iontophoresis)"], "ans": 3, "exp": "Confirmatory lab test: sweat chloride >60 mEq/L on separate days by pilocarpine iontophoresis. (Book p132)", "type": "case"},
 {"id": "PEDS-C29-064", "sec": "Respiratory care", "page": 132, "q": "Respiratory care in cystic fibrosis rests on three pillars —", "opts": ["Airway clearance, antibiotics & prophylaxis", "Ventilation, diuretics & steroids", "Bronchoscopy, steroids & surgery", "Oxygen, diuretics & vaccines"], "ans": 0, "exp": "Respiratory care: airway clearance, antibiotics, prophylaxis (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-065", "sec": "Airway clearance", "page": 132, "q": "Airway clearance in CF includes —", "opts": ["Tracheostomy", "Physiotherapy", "Daily contrast enema", "Weekly bronchoscopy"], "ans": 1, "exp": "Airway clearance: 1. physiotherapy; 2. mucolytics (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-066", "sec": "Airway clearance", "page": 132, "q": "Mucolytics used in CF include —", "opts": ["Inhaled budesonide and oral acetylcysteine", "Nebulized racemic epinephrine and normal saline", "Inhaled hypertonic saline (3%) and human recombinant DNase", "Oral guaifenesin and nebulized salbutamol"], "ans": 2, "exp": "Mucolytics: inhaled hypertonic saline (3%); human recombinant DNase (human dornase alfa) (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-067", "sec": "Airway clearance", "page": 132, "q": "Hypertonic saline used for CF airway clearance is ___ %.", "opts": ["0.9", "5", "7.5", "3"], "ans": 3, "exp": "Inhaled hypertonic saline (3%) (Book p132)", "type": "fill"},
 {"id": "PEDS-C29-068", "sec": "Airway clearance", "page": 132, "q": "The recombinant DNase mucolytic used in CF is —", "opts": ["Human DNase alpha (dornase alfa)", "Streptokinase", "Hyaluronidase", "Recombinant heparinase"], "ans": 0, "exp": "Human recombinant DNase (human dornase alfa) (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-069", "sec": "Antibiotics", "page": 132, "q": "The drug of choice antibiotic in CF pulmonary infection is —", "opts": ["Vancomycin reserved for resistant staphylococci", "Co-amoxiclav (amoxicillin + clavulanic acid)", "Azithromycin as a single oral agent", "Ceftriaxone given intramuscularly once daily"], "ans": 1, "exp": "Antibiotics: co-amoxiclav (DOC) (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-070", "sec": "Antibiotics", "page": 132, "q": "Another antibiotic option for CF pulmonary infections is —", "opts": ["Oral metronidazole", "IV amphotericin B", "Fluoroquinolones", "Aminoglycosides alone"], "ans": 2, "exp": "Antibiotics: co-amoxiclav (DOC), fluoroquinolone, azithromycin (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-071", "sec": "Antibiotics", "page": 132, "q": "Azithromycin in CF is used —", "opts": ["Only for acute otitis media", "As a mucolytic agent", "For pancreatic enzyme replacement", "As an antibiotic and for Pseudomonas prophylaxis"], "ans": 3, "exp": "Azithromycin is listed both as an antibiotic and (oral) for Pseudomonas prophylaxis (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-072", "sec": "Prophylaxis", "page": 132, "q": "Pseudomonas prophylaxis in CF is given three times a week to decrease —", "opts": ["Colonization", "Immunity", "Mucus viscosity", "Appetite"], "ans": 0, "exp": "For Pseudomonas infection: 3 times a week decreases colonization (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-073", "sec": "Prophylaxis", "page": 132, "q": "Inhaled Pseudomonas prophylaxis in CF includes —", "opts": ["Hypertonic saline", "Tobramycin or aztreonam", "Budesonide", "Salbutamol"], "ans": 1, "exp": "Inhaled tobramycin/aztreonam (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-074", "sec": "Prophylaxis", "page": 132, "q": "Oral Pseudomonas prophylaxis in CF is —", "opts": ["Vancomycin", "Cotrimoxazole", "Azithromycin", "Ciprofloxacin"], "ans": 2, "exp": "Oral azithromycin (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-075", "sec": "Respiratory care", "page": 132, "q": "Match the CF respiratory care pillar — select the correct combination:", "pairs": [["Airway clearance", "Tobramycin/aztreonam"], ["DOC antibiotic", "Physiotherapy + mucolytics"], ["Inhaled Pseudomonas prophylaxis", "Co-amoxiclav"], ["Oral Pseudomonas prophylaxis", "Azithromycin"]], "opts": ["A-2, B-3, C-4, D-1", "A-4, B-2, C-1, D-3", "A-2, B-1, C-3, D-4", "A-2, B-3, C-1, D-4"], "ans": 3, "exp": "Correct: clearance→physiotherapy + mucolytics; DOC→co-amoxiclav; inhaled prophylaxis→tobramycin/aztreonam; oral prophylaxis→azithromycin. (Book p132)", "type": "match"},
 {"id": "PEDS-C29-076", "sec": "Prophylaxis", "page": 132, "stem": "A 7-year-old with CF has sputum cultures growing Pseudomonas aeruginosa. To reduce further colonization, a thrice-weekly prophylactic regimen is planned.", "q": "The appropriate inhaled prophylaxis is —", "opts": ["Tobramycin three times a week", "Meropenem once daily", "Budesonide once daily", "Ciprofloxacin once daily"], "ans": 0, "exp": "Inhaled tobramycin/aztreonam 3×/week decreases Pseudomonas colonization. (Book p132)", "type": "case"},
 {"id": "PEDS-C29-077", "sec": "Dietary measures", "page": 132, "q": "The diet recommended in cystic fibrosis is high in —", "opts": ["Clear fluids and electrolytes", "Fat, protein and calories", "Fiber and water only", "Sugars with restricted fat"], "ans": 1, "exp": "Diet: high fat, protein, calories (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-078", "sec": "Dietary measures", "page": 132, "q": "Salt supplementation in CF is given —", "opts": ["Only in the neonatal period", "Only in winter months", "More during dehydration", "Avoided completely"], "ans": 2, "exp": "Salt supplementation (more during dehydration) (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-079", "sec": "Dietary measures", "page": 132, "q": "Pancreatic enzyme supplements in CF are given as —", "opts": ["Sublingual tablets", "Intravenous infusions", "Rectal suppositories", "Enterically coated microspheres"], "ans": 3, "exp": "Pancreatic enzyme supplements (enterically coated microspheres) (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-080", "sec": "Dietary measures", "page": 132, "q": "Fat-soluble vitamins supplemented in CF include —", "opts": ["A, D, E & K", "B1, B6 & B12", "C, E & K", "A, C, D & E"], "ans": 0, "exp": "Fat soluble vitamin supplementation (A, D, E & K) (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-081", "sec": "CFTR modulators", "page": 132, "q": "CFTR modulators work by decreasing the activity of the CFTR channel.", "opts": ["True", "False"], "ans": 1, "exp": "False — CFTR modulators ↑ activity of CFTR channel (Book p132)", "type": "tf"},
 {"id": "PEDS-C29-082", "sec": "CFTR modulators", "page": 132, "q": "Ivacaftor can be used from the age of —", "opts": [">12 years", ">18 years", ">2 years", ">6 years"], "ans": 2, "exp": "Ivacaftor (>2 years) (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-083", "sec": "CFTR modulators", "page": 132, "q": "Ivacaftor + lumacaftor is useful in ___ mutation cases.", "opts": ["All CF mutations", "Only G551D", "Only nonsense mutations", "ΔF508"], "ans": 3, "exp": "Ivacaftor + lumacaftor (>6 years): useful in ΔF508 mutation cases (Book p132)", "type": "fill"},
 {"id": "PEDS-C29-084", "sec": "CFTR modulators", "page": 132, "q": "Ivacaftor + tezacaftor is used from the age of —", "opts": [">12 years", ">2 years", ">6 years", ">16 years"], "ans": 0, "exp": "Ivacaftor + tezacaftor (>12 years) (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-085", "sec": "CFTR modulators", "page": 132, "q": "The triple combination CFTR therapy is —", "opts": ["Tezacaftor + elexacaftor without ivacaftor", "Ivacaftor + tezacaftor + elexacaftor", "Ivacaftor + lumacaftor + tezacaftor", "Ivacaftor + elexacaftor"], "ans": 1, "exp": "Triple combination therapy: ivacaftor + tezacaftor + elexacaftor (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-086", "sec": "CFTR modulators", "page": 132, "q": "The triple combination CFTR therapy covers —", "opts": ["Only female patients", "No known mutations", "Most mutations", "Only ΔF508 homozygotes"], "ans": 2, "exp": "Triple combination therapy: covers most mutations (Book p132)", "type": "mcq"},
 {"id": "PEDS-C29-087", "sec": "CFTR modulators", "page": 132, "q": "Match the CFTR modulator — select the correct combination:", "pairs": [["Ivacaftor", ">6 years, useful in ΔF508"], ["Ivacaftor + lumacaftor", ">12 years"], ["Ivacaftor + tezacaftor", "Covers most mutations"], ["Triple (ivacaftor + tezacaftor + elexacaftor)", ">2 years"]], "opts": ["A-4, B-1, C-3, D-2", "A-2, B-1, C-4, D-3", "A-4, B-2, C-1, D-3", "A-4, B-1, C-2, D-3"], "ans": 3, "exp": "Correct: ivacaftor→>2 yrs; +lumacaftor→>6 yrs, ΔF508; +tezacaftor→>12 yrs; triple→covers most mutations. (Book p132)", "type": "match"},
 {"id": "PEDS-C29-088", "sec": "CFTR modulators", "page": 132, "stem": "A 7-year-old with cystic fibrosis is homozygous for the ΔF508 mutation and needs CFTR modulator therapy.", "q": "The combination indicated per the book is —", "opts": ["Ivacaftor + lumacaftor", "Ivacaftor alone", "Ivacaftor + tezacaftor", "Elexacaftor alone"], "ans": 0, "exp": "Ivacaftor + lumacaftor (>6 years): useful in ΔF508 mutation cases. (Book p132)", "type": "case"},
